-- Deployment-owned autonomous manager. No resident content or provider credential.
CREATE TABLE tower_autonomy_mandate(id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), enabled_at TEXT, updated_at TEXT NOT NULL, task_limit_micro INTEGER NOT NULL DEFAULT 10000000 CHECK(task_limit_micro BETWEEN 1 AND 10000000), daily_limit_micro INTEGER NOT NULL DEFAULT 10000000 CHECK(daily_limit_micro BETWEEN 1 AND 10000000), daily_task_limit INTEGER NOT NULL DEFAULT 1 CHECK(daily_task_limit=1));
INSERT INTO tower_autonomy_mandate(id,updated_at) VALUES(1,'2026-10-31T00:00:00.000Z');
CREATE TABLE tower_autonomy_cycles(id TEXT PRIMARY KEY, day TEXT NOT NULL UNIQUE, state TEXT NOT NULL CHECK(state IN ('thinking','execute','image-day','image-night','verify','tool-result','audit','activate','selfreview','complete','blocked')), purpose TEXT NOT NULL, outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN ('pending','pass','blocked')), tool_json TEXT CHECK(tool_json IS NULL OR json_valid(tool_json)), acceptance_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(acceptance_json)), permissions_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(permissions_json)), budget_micro INTEGER NOT NULL CHECK(budget_micro BETWEEN 1 AND 10000000), plan_json TEXT CHECK(plan_json IS NULL OR json_valid(plan_json)), evidence_json TEXT CHECK(evidence_json IS NULL OR json_valid(evidence_json)), audit_json TEXT CHECK(audit_json IS NULL OR json_valid(audit_json)), review_json TEXT CHECK(review_json IS NULL OR json_valid(review_json)), repair INTEGER NOT NULL DEFAULT 0 CHECK(repair BETWEEN 0 AND 1), step_seq INTEGER NOT NULL DEFAULT 0, lease_until TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE tower_autonomy_calls(id TEXT PRIMARY KEY, cycle_id TEXT NOT NULL REFERENCES tower_autonomy_cycles(id), step_key TEXT NOT NULL UNIQUE, purpose TEXT NOT NULL, model TEXT NOT NULL, billing_day TEXT NOT NULL CHECK(billing_day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), state TEXT NOT NULL CHECK(state IN ('dispatching','received','rejected','unknown')), reserved_micro INTEGER NOT NULL CHECK(reserved_micro>=0), actual_micro INTEGER CHECK(actual_micro IS NULL OR actual_micro>=0), input_tokens INTEGER, output_tokens INTEGER, provider_id TEXT, created_at TEXT NOT NULL, completed_at TEXT, CHECK((state IN ('dispatching','unknown') AND actual_micro IS NULL) OR state IN ('received','rejected')));
CREATE TRIGGER tower_autonomy_call_binding BEFORE UPDATE ON tower_autonomy_calls WHEN NEW.id!=OLD.id OR NEW.cycle_id!=OLD.cycle_id OR NEW.step_key!=OLD.step_key OR NEW.purpose!=OLD.purpose OR NEW.model!=OLD.model OR NEW.billing_day!=OLD.billing_day OR NEW.reserved_micro!=OLD.reserved_micro OR NEW.created_at!=OLD.created_at OR OLD.state!='dispatching' BEGIN SELECT RAISE(ABORT,'autonomy_call_immutable'); END;
CREATE TRIGGER tower_autonomy_call_permanent BEFORE DELETE ON tower_autonomy_calls BEGIN SELECT RAISE(ABORT,'autonomy_call_immutable'); END;
CREATE TABLE tower_autonomy_events(id TEXT PRIMARY KEY,cycle_id TEXT REFERENCES tower_autonomy_cycles(id),kind TEXT NOT NULL,detail_json TEXT NOT NULL CHECK(json_valid(detail_json)),created_at TEXT NOT NULL);
CREATE TRIGGER tower_autonomy_events_update BEFORE UPDATE ON tower_autonomy_events BEGIN SELECT RAISE(ABORT,'autonomy_event_immutable'); END;
CREATE TRIGGER tower_autonomy_events_delete BEFORE DELETE ON tower_autonomy_events BEGIN SELECT RAISE(ABORT,'autonomy_event_immutable'); END;
CREATE TABLE tower_autonomy_assets(generation_id TEXT NOT NULL,scene TEXT NOT NULL CHECK(scene IN ('day','night')),cycle_id TEXT NOT NULL REFERENCES tower_autonomy_cycles(id),object_key TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,bytes INTEGER NOT NULL,provider_call_id TEXT NOT NULL REFERENCES tower_autonomy_calls(id),created_at TEXT NOT NULL,PRIMARY KEY(generation_id,scene));
CREATE TRIGGER tower_autonomy_assets_update BEFORE UPDATE ON tower_autonomy_assets BEGIN SELECT RAISE(ABORT,'autonomy_asset_immutable'); END;
CREATE TRIGGER tower_autonomy_assets_delete BEFORE DELETE ON tower_autonomy_assets BEGIN SELECT RAISE(ABORT,'autonomy_asset_immutable'); END;
CREATE TABLE tower_autonomy_current(id INTEGER PRIMARY KEY CHECK(id=1),generation_id TEXT NOT NULL,cycle_id TEXT NOT NULL REFERENCES tower_autonomy_cycles(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0));
CREATE TRIGGER tower_autonomy_current_guard BEFORE INSERT ON tower_autonomy_current WHEN NOT EXISTS(SELECT 1 FROM tower_autonomy_cycles c WHERE c.id=NEW.cycle_id AND c.state='activate' AND EXISTS(SELECT 1 FROM tower_autonomy_authorizations a JOIN tower_autonomy_task_anchors t ON t.cycle_id=a.cycle_id WHERE a.cycle_id=c.id AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND json_extract(c.evidence_json,'$.generation')=NEW.generation_id AND EXISTS(SELECT 1 FROM json_each(c.permissions_json) WHERE value='activate-reviewed-exterior') AND EXISTS(SELECT 1 FROM tower_autonomy_calls a WHERE a.id=json_extract(c.audit_json,'$.callId') AND a.cycle_id=c.id AND a.purpose='independent-task-audit' AND a.model='muse-spark-1.3' AND a.state='received')) OR (SELECT count(*) FROM tower_autonomy_assets WHERE generation_id=NEW.generation_id AND cycle_id=NEW.cycle_id)!=2 BEGIN SELECT RAISE(ABORT,'autonomy_activation_denied'); END;
CREATE TRIGGER tower_autonomy_current_update_guard BEFORE UPDATE ON tower_autonomy_current WHEN NEW.revision!=OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM tower_autonomy_cycles c WHERE c.id=NEW.cycle_id AND c.state='activate' AND EXISTS(SELECT 1 FROM tower_autonomy_authorizations a JOIN tower_autonomy_task_anchors t ON t.cycle_id=a.cycle_id WHERE a.cycle_id=c.id AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND json_extract(c.evidence_json,'$.generation')=NEW.generation_id AND EXISTS(SELECT 1 FROM json_each(c.permissions_json) WHERE value='activate-reviewed-exterior') AND EXISTS(SELECT 1 FROM tower_autonomy_calls a WHERE a.id=json_extract(c.audit_json,'$.callId') AND a.cycle_id=c.id AND a.purpose='independent-task-audit' AND a.model='muse-spark-1.3' AND a.state='received')) OR (SELECT count(*) FROM tower_autonomy_assets WHERE generation_id=NEW.generation_id AND cycle_id=NEW.cycle_id)!=2 BEGIN SELECT RAISE(ABORT,'autonomy_activation_denied'); END;

CREATE TABLE tower_autonomy_task_anchors(anchor TEXT PRIMARY KEY,cycle_id TEXT NOT NULL UNIQUE REFERENCES tower_autonomy_cycles(id),created_at TEXT NOT NULL);
CREATE TRIGGER tower_autonomy_anchor_update BEFORE UPDATE ON tower_autonomy_task_anchors BEGIN SELECT RAISE(ABORT,'autonomy_anchor_immutable'); END;
CREATE TRIGGER tower_autonomy_anchor_delete BEFORE DELETE ON tower_autonomy_task_anchors BEGIN SELECT RAISE(ABORT,'autonomy_anchor_immutable'); END;
CREATE TRIGGER tower_autonomy_anchor_replace BEFORE INSERT ON tower_autonomy_task_anchors WHEN EXISTS(SELECT 1 FROM tower_autonomy_task_anchors WHERE anchor=NEW.anchor OR cycle_id=NEW.cycle_id) BEGIN SELECT RAISE(ABORT,'autonomy_anchor_immutable'); END;
CREATE TRIGGER tower_autonomy_cycle_binding BEFORE UPDATE ON tower_autonomy_cycles WHEN NEW.id!=OLD.id OR NEW.day!=OLD.day OR NEW.created_at!=OLD.created_at OR (OLD.state!='thinking' AND (NEW.budget_micro!=OLD.budget_micro OR NEW.purpose!=OLD.purpose OR NEW.acceptance_json!=OLD.acceptance_json OR NEW.permissions_json!=OLD.permissions_json)) BEGIN SELECT RAISE(ABORT,'autonomy_task_binding_immutable'); END;
CREATE TRIGGER tower_autonomy_cycle_replace BEFORE INSERT ON tower_autonomy_cycles WHEN EXISTS(SELECT 1 FROM tower_autonomy_cycles WHERE id=NEW.id OR day=NEW.day) BEGIN SELECT RAISE(ABORT,'autonomy_task_binding_immutable'); END;
CREATE TRIGGER tower_autonomy_cycle_delete BEFORE DELETE ON tower_autonomy_cycles BEGIN SELECT RAISE(ABORT,'autonomy_task_permanent'); END;
CREATE TRIGGER tower_autonomy_call_replace BEFORE INSERT ON tower_autonomy_calls WHEN EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE id=NEW.id OR step_key=NEW.step_key) BEGIN SELECT RAISE(ABORT,'autonomy_call_immutable'); END;
CREATE TRIGGER tower_autonomy_events_replace BEFORE INSERT ON tower_autonomy_events WHEN EXISTS(SELECT 1 FROM tower_autonomy_events WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'autonomy_event_immutable'); END;
CREATE TRIGGER tower_autonomy_assets_replace BEFORE INSERT ON tower_autonomy_assets WHEN EXISTS(SELECT 1 FROM tower_autonomy_assets WHERE generation_id=NEW.generation_id AND scene=NEW.scene OR object_key=NEW.object_key) BEGIN SELECT RAISE(ABORT,'autonomy_asset_immutable'); END;
CREATE TRIGGER tower_autonomy_assets_provenance BEFORE INSERT ON tower_autonomy_assets WHEN NOT EXISTS(SELECT 1 FROM tower_autonomy_calls a JOIN tower_autonomy_cycles c ON c.id=a.cycle_id WHERE a.id=NEW.provider_call_id AND a.cycle_id=NEW.cycle_id AND a.model='muse-image-1.0' AND a.state='received' AND a.actual_micro=10000 AND a.purpose='image-'||NEW.scene||'-r'||c.repair AND c.state='image-'||NEW.scene AND NEW.generation_id=c.id||'-r'||c.repair) BEGIN SELECT RAISE(ABORT,'autonomy_asset_provenance'); END;
CREATE TRIGGER tower_autonomy_current_native_clock BEFORE INSERT ON tower_autonomy_current WHEN NEW.starts_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.ends_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)!=1 OR EXISTS(SELECT 1 FROM tower_autonomy_current WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'autonomy_activation_clock_or_mandate'); END;
CREATE TRIGGER tower_autonomy_current_update_clock BEFORE UPDATE ON tower_autonomy_current WHEN NEW.starts_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.ends_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_activation_clock_or_mandate'); END;
CREATE TRIGGER tower_autonomy_current_permanent BEFORE DELETE ON tower_autonomy_current BEGIN SELECT RAISE(ABORT,'autonomy_current_permanent'); END;

CREATE INDEX tower_autonomy_calls_billing_day ON tower_autonomy_calls(billing_day);
-- Policy bc-pct-2026-10-30: B.C. final transition2026-03-08T10Z, permanentUTC-7 thereafter. Historical2007-2025 retains former seasonal boundaries.
-- Exact dispatch-local day derives from immutable created_at, never from the task's original day.
CREATE TRIGGER tower_autonomy_call_billing_guard BEFORE INSERT ON tower_autonomy_calls WHEN NEW.billing_day!=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) OR julianday(NEW.created_at) IS NULL OR abs(julianday(NEW.created_at)-julianday('now'))>1.5 OR NEW.billing_day!=date(NEW.created_at,CASE WHEN NEW.created_at>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN NEW.created_at>=date(substr(NEW.created_at,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND NEW.created_at<date(substr(NEW.created_at,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) OR (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE billing_day=NEW.billing_day)+NEW.reserved_micro>(SELECT daily_limit_micro FROM tower_autonomy_mandate WHERE id=1) OR (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=NEW.cycle_id)+NEW.reserved_micro>(SELECT budget_micro FROM tower_autonomy_cycles WHERE id=NEW.cycle_id) BEGIN SELECT RAISE(ABORT,'autonomy_dispatch_day_or_budget'); END;

-- One immutable authorization per logical task, committed atomically with its initial plan and anchor.
CREATE TABLE tower_autonomy_authorizations(cycle_id TEXT PRIMARY KEY REFERENCES tower_autonomy_cycles(id),day TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('noop','health','appearance')),budget_micro INTEGER NOT NULL CHECK(budget_micro BETWEEN 1 AND 10000000),granted_seq INTEGER NOT NULL CHECK(granted_seq>0),starts_at TEXT,ends_at TEXT,calendar_policy TEXT NOT NULL CHECK(calendar_policy='bc-pct-2026-10-30'),created_at TEXT NOT NULL,CHECK((kind='appearance' AND starts_at='2026-10-31T07:00:00.000Z' AND ends_at='2026-11-01T07:00:00.000Z') OR (kind IN ('noop','health') AND starts_at IS NULL AND ends_at IS NULL)));
CREATE TRIGGER tower_autonomy_authorization_update BEFORE UPDATE ON tower_autonomy_authorizations BEGIN SELECT RAISE(ABORT,'autonomy_authorization_immutable'); END;
CREATE TRIGGER tower_autonomy_authorization_delete BEFORE DELETE ON tower_autonomy_authorizations BEGIN SELECT RAISE(ABORT,'autonomy_authorization_immutable'); END;
CREATE TRIGGER tower_autonomy_authorization_replace BEFORE INSERT ON tower_autonomy_authorizations WHEN EXISTS(SELECT 1 FROM tower_autonomy_authorizations WHERE cycle_id=NEW.cycle_id) BEGIN SELECT RAISE(ABORT,'autonomy_authorization_immutable'); END;
CREATE UNIQUE INDEX tower_autonomy_action_audit ON tower_autonomy_events(cycle_id) WHERE kind='action-authorized';
CREATE TRIGGER tower_autonomy_initial_action_guard BEFORE UPDATE ON tower_autonomy_cycles WHEN OLD.state='thinking' AND NEW.state IN ('execute','verify') AND COALESCE((NEW.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND NEW.day=date(NEW.updated_at,CASE WHEN NEW.updated_at>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN NEW.updated_at>=date(substr(NEW.updated_at,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND NEW.updated_at<date(substr(NEW.updated_at,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) AND OLD.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND OLD.lease_until>NEW.updated_at AND NEW.step_seq=OLD.step_seq+1 AND NEW.lease_until IS NULL AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND EXISTS(SELECT 1 FROM tower_autonomy_calls a WHERE a.cycle_id=OLD.id AND a.step_key=OLD.id||':'||OLD.step_seq||':daily-thinking' AND a.purpose='daily-thinking' AND a.state='received') AND NEW.budget_micro>=(SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=OLD.id)+CASE WHEN NEW.state='execute' THEN 1700000 ELSE 400000 END AND ((NEW.state='verify' AND json_extract(NEW.plan_json,'$.kind') IN ('noop','health')) OR (NEW.state='execute' AND json_extract(NEW.plan_json,'$.kind')='appearance' AND NEW.day='2026-10-31' AND '2026-10-31T07:00:00.000Z'<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND strftime('%Y-%m-%dT%H:%M:%fZ','now')<'2026-11-01T07:00:00.000Z' AND NEW.updated_at>='2026-10-31T07:00:00.000Z' AND NEW.updated_at<'2026-11-01T07:00:00.000Z' AND EXISTS(SELECT 1 FROM json_each(NEW.permissions_json) WHERE value='edit-exterior-images') AND EXISTS(SELECT 1 FROM json_each(NEW.permissions_json) WHERE value='activate-reviewed-exterior')))),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_action_authorization'); END;
CREATE TRIGGER tower_autonomy_authorization_guard BEFORE INSERT ON tower_autonomy_authorizations WHEN COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_cycles c WHERE c.id=NEW.cycle_id AND c.day=NEW.day AND c.updated_at=NEW.created_at AND c.budget_micro=NEW.budget_micro AND c.step_seq=NEW.granted_seq AND json_extract(c.plan_json,'$.kind')=NEW.kind AND c.state=CASE WHEN NEW.kind='appearance' THEN 'execute' ELSE 'verify' END) AND NEW.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND NEW.day=date(NEW.created_at,CASE WHEN NEW.created_at>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN NEW.created_at>=date(substr(NEW.created_at,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND NEW.created_at<date(substr(NEW.created_at,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND (NEW.kind!='appearance' OR (NEW.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NEW.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NEW.starts_at<=NEW.created_at AND NEW.ends_at>NEW.created_at))),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_action_authorization'); END;
CREATE TRIGGER tower_autonomy_anchor_scope BEFORE INSERT ON tower_autonomy_task_anchors WHEN COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_authorizations a JOIN tower_autonomy_cycles c ON c.id=a.cycle_id WHERE a.cycle_id=NEW.cycle_id AND a.kind='appearance' AND c.state='execute' AND c.step_seq=a.granted_seq AND c.updated_at=a.created_at AND NEW.created_at=a.created_at AND NEW.anchor='appearance:halloween:2026' AND a.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_anchor_scope'); END;
CREATE TRIGGER tower_autonomy_action_audit_guard BEFORE INSERT ON tower_autonomy_events WHEN NEW.kind='action-authorized' AND COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_authorizations a WHERE a.cycle_id=NEW.cycle_id AND a.created_at=NEW.created_at AND a.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND (a.kind!='appearance' OR (a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')))) AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_action_audit'); END;
CREATE TRIGGER tower_autonomy_action_transition_guard BEFORE UPDATE ON tower_autonomy_cycles WHEN OLD.state!='thinking' AND NEW.state!=OLD.state AND NEW.state IN ('execute','image-day','image-night','activate') AND COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_authorizations a JOIN tower_autonomy_task_anchors t ON t.cycle_id=a.cycle_id WHERE a.cycle_id=OLD.id AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND a.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.starts_at<=NEW.updated_at AND a.ends_at>NEW.updated_at) AND OLD.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND OLD.lease_until>NEW.updated_at AND NEW.step_seq=OLD.step_seq+1 AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_tool_scope'); END;
CREATE TRIGGER tower_autonomy_paid_tool_scope BEFORE INSERT ON tower_autonomy_calls WHEN (NEW.model='muse-image-1.0' OR NEW.purpose IN ('tool-executor','tool-executor:input-token-count')) AND COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_authorizations a JOIN tower_autonomy_cycles c ON c.id=a.cycle_id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=NEW.cycle_id AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND a.day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND a.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND a.starts_at<=NEW.created_at AND a.ends_at>NEW.created_at AND c.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.lease_until>NEW.created_at AND ((NEW.model='muse-image-1.0' AND c.state IN ('image-day','image-night') AND NEW.purpose=c.state||'-r'||c.repair) OR (NEW.purpose IN ('tool-executor','tool-executor:input-token-count') AND c.state='execute'))) AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1),0)!=1 BEGIN SELECT RAISE(ABORT,'autonomy_tool_scope'); END;
